//! Property tests: callees generated by `build.rs` with random signatures
//! (fixed seed) and every signature of up to two parameters. Each case
//! calls the callee directly and through `yavs_ffi::call` and compares
//! the result and a position-sensitive hash of the arguments it saw.

use std::cell::Cell;
use std::ffi::c_void;

use yavs_ffi::{Arg, CType, Ret, Signature, call};

const SEED: u64 = 0x9e37_79b9_7f4a_7c15;

fn step(h: u64, v: u64) -> u64 {
    (h.rotate_left(5) ^ v).wrapping_mul(0x0100_0000_01b3)
}

thread_local!(static LAST: Cell<u64> = const { Cell::new(0) });

fn set_last(h: u64) {
    LAST.with(|l| l.set(h));
}

fn last() -> u64 {
    LAST.with(Cell::get)
}

trait Mix {
    fn mix(self) -> u64;
}

macro_rules! mix_int {
    ($($t:ty),*) => { $(impl Mix for $t { fn mix(self) -> u64 { self as i64 as u64 } })* };
}
mix_int!(i8, i16, i32, i64, u8, u16, u32);

impl Mix for f32 {
    fn mix(self) -> u64 {
        self.to_bits().into()
    }
}

impl Mix for f64 {
    fn mix(self) -> u64 {
        self.to_bits()
    }
}

impl Mix for *mut c_void {
    fn mix(self) -> u64 {
        self as usize as u64
    }
}

// The calls are sound: every callee has exactly the declared signature.
#[allow(unsafe_code, unused_parens, unused_mut, clippy::all, clippy::pedantic)]
mod cases {
    use super::*;
    include!(concat!(env!("OUT_DIR"), "/gen_cases.rs"));
}

#[test]
fn generated_signatures_match_direct_calls() {
    for case in cases::CASES {
        case();
    }
    assert_eq!(cases::CASES.len(), 111 + 320);
}
